Okay...you don't need any kind of big plugin for this. I was hoping one of your searches led you to the many threads with snippets posted directly in there.
So you can paste the below into a text editor, save as a *.js file, include as a plugin.
Code:
Window_Status.prototype.drawParameters = function(x, y) {
    var lineHeight = this.lineHeight();
    for (var i = 0; i < 6; i++) {
        var paramId = i + 2;
        if ((paramId == 4 || paramId == 5) && this._actor.actorId() == 42)
            continue;
        var y2 = y + lineHeight * i;
        this.changeTextColor(this.systemColor());
        this.drawText(TextManager.param(paramId), x, y2, 160);
        this.resetTextColor();
        this.drawText(this._actor.param(paramId), x + 160, y2, 60, 'right');
    }
};
Replace 42 with the actor ID you're making this change for.
As far as MP, if you're using Yanfly plugins one of them should have the option right in the notetags to remove a gauge from an actor.

